      "manifest": {
        "$schema": "../../../docs/schemas/ragbaz.component.schema.json",
        "schemaVersion": "0.1.0",
        "identity": {
          "id": "articulate.wp-sidecar",
          "name": "Articulate WordPress Sidecar",
          "version": "0.1.0",
          "repoPath": "products/articulate/wp-sidecar",
          "owner": "ragbaz",
          "lifecycle": "prototype"
        },
        "commercial": {
          "packageTags": [
            "secure-wordpress-runtime",
            "headless-course-shop"
          ],
          "personas": [
            "internal-operator",
            "agency",
            "publisher"
          ],
          "supportTier": "managed",
          "salesStatus": "internal",
          "pricingTags": [
            "included-runtime"
          ]
        },
        "capabilities": {
          "provides": [
            {
              "id": "wordpress.runtime",
              "label": "WordPress sidecar runtime",
              "version": "0.1.0",
              "supportTier": "prototype",
              "description": "Rust ingress and PHP-FPM WordPress sidecar over a private Unix socket."
            },
            {
              "id": "wordpress.uploads.hardened",
              "label": "Hardened upload endpoint",
              "version": "0.1.0",
              "supportTier": "prototype",
              "sensitive": true,
              "description": "Upload policy with body limits, random file IDs, SHA-256 hashing, and storage outside the WordPress tree."
            }
          ]
        },
        "requires": {
          "storage": [
            {
              "name": "wordpress-core",
              "reason": "Host-visible WordPress core tree."
            },
            {
              "name": "uploads",
              "reason": "Out-of-tree upload storage."
            }
          ],
          "network": [
            {
              "name": "private-php-fpm-socket",
              "reason": "PHP-FPM is exposed only over a Unix socket."
            }
          ]
        },
        "provides": {
          "endpoints": [
            {
              "name": "gateway",
              "protocol": "http",
              "urlEnv": "WP_SIDECAR_URL",
              "capabilities": [
                "wordpress.runtime",
                "wordpress.uploads.hardened"
              ],
              "auth": "none",
              "tenantScoped": true
            }
          ],
          "metrics": [
            {
              "name": "upload-policy",
              "description": "Upload request limits, accepted files, and hash outcomes.",
              "capabilities": [
                "wordpress.uploads.hardened"
              ]
            }
          ],
          "adminSurfaces": [
            {
              "name": "docker-compose",
              "description": "Local sidecar stack and bootstrap operations.",
              "capabilities": [
                "wordpress.runtime"
              ]
            }
          ]
        },
        "config": {
          "knobs": [
            {
              "name": "bind",
              "env": "BIND",
              "type": "string",
              "required": false,
              "control": "operator",
              "description": "Gateway bind address."
            },
            {
              "name": "upload-limit",
              "env": "UPLOAD_LIMIT_BYTES",
              "type": "integer",
              "required": false,
              "control": "operator",
              "description": "Maximum upload body size."
            }
          ]
        },
        "security": {
          "authMethods": [
            "none"
          ],
          "tenantBoundary": "single-tenant",
          "dataClasses": [
            "public",
            "tenant-content",
            "logs"
          ],
          "secretAccess": "references-only",
          "revocation": "Stop the sidecar stack and rotate any WordPress admin credentials outside this component.",
          "auditEvents": [
            "wordpress.upload.accepted",
            "wordpress.upload.rejected"
          ]
        },
        "health": {
          "checks": [
            {
              "name": "gateway-health",
              "type": "http",
              "target": "/health",
              "intervalSeconds": 120,
              "timeoutSeconds": 10,
              "required": true
            }
          ]
        },
        "compatibility": {
          "contracts": [
            {
              "name": "wordpress-sidecar",
              "version": "0.1.0",
              "test": "cargo test"
            }
          ]
        },
        "docs": {
          "readme": "README.md",
          "architecture": "docs/DECISIONS.md"
        },
        "metadata": {
          "candidateWave": "component-manifest-candidate-wave"
        }
      },
