      "manifest": {
        "$schema": "../../docs/schemas/ragbaz.component.schema.json",
        "schemaVersion": "0.1.0",
        "identity": {
          "id": "detcordon.appliance",
          "name": "DetCordon Appliance",
          "version": "0.1.0",
          "repoPath": "products/detcordon",
          "owner": "ragbaz",
          "lifecycle": "prototype"
        },
        "commercial": {
          "packageTags": [
            "detcordon-appliance",
            "security-research"
          ],
          "personas": [
            "security-researcher",
            "blue-team",
            "research-lab"
          ],
          "supportTier": "managed",
          "salesStatus": "demo",
          "pricingTags": [
            "appliance",
            "managed-lab"
          ]
        },
        "capabilities": {
          "provides": [
            {
              "id": "security.malware.observation",
              "label": "Contained malware observation",
              "version": "0.1.0",
              "supportTier": "demo",
              "sensitive": true,
              "description": "Detection-only web malware detonation topology with separated sandbox VM and sink host."
            },
            {
              "id": "artifact.evidence",
              "label": "Encrypted evidence artifacts",
              "version": "0.1.0",
              "supportTier": "demo",
              "sensitive": true,
              "description": "Stores sample bodies age-encrypted by sha256 path with UDP telemetry and TCP sample transfer."
            }
          ]
        },
        "requires": {
          "secrets": [
            {
              "name": "WAF_SINK_RECIPIENT",
              "description": "Age recipient public key used to encrypt samples at rest.",
              "materialization": "environment"
            }
          ],
          "network": [
            {
              "name": "separate-sandbox-and-sink-hosts",
              "reason": "Containment model requires a sandbox VM and a separate sink host."
            },
            {
              "name": "default-drop-egress",
              "reason": "Victim environment should only reach controlled DNS and sink channels."
            }
          ],
          "approvals": [
            {
              "capability": "approval.hostile.samples",
              "reason": "Running hostile samples requires explicit operator safety approval."
            }
          ]
        },
        "provides": {
          "endpoints": [
            {
              "name": "waf-tap",
              "protocol": "http",
              "urlEnv": "DETCORDON_WAF_URL",
              "capabilities": [
                "security.malware.observation"
              ],
              "auth": "none",
              "tenantScoped": false
            },
            {
              "name": "sink-events",
              "protocol": "tcp",
              "urlEnv": "SINK_TCP_ADDR",
              "capabilities": [
                "artifact.evidence"
              ],
              "auth": "none",
              "tenantScoped": false
            }
          ],
          "artifacts": [
            {
              "name": "sandbox-deploy",
              "mediaType": "application/vnd.ragbaz.detcordon.sandbox+json",
              "digestRequired": true,
              "signatureRequired": true
            },
            {
              "name": "encrypted-sample",
              "mediaType": "application/vnd.ragbaz.detcordon.sample+age",
              "digestRequired": true,
              "signatureRequired": false
            }
          ],
          "cli": [
            {
              "name": "waf-deploy",
              "command": "cargo run -p waf-deploy",
              "capabilities": [
                "security.malware.observation"
              ]
            }
          ],
          "events": [
            {
              "type": "detcordon.event.observed",
              "schemaVersion": "0.1.0",
              "description": "Detection-only HTTP or process telemetry emitted from the sandbox."
            },
            {
              "type": "detcordon.sample.stored",
              "schemaVersion": "0.1.0",
              "description": "Encrypted sample stored by digest on the sink host."
            }
          ],
          "adminSurfaces": [
            {
              "name": "deploy-tui",
              "description": "Ratatui deployment artifact generator for sandbox and sink topology.",
              "capabilities": [
                "security.malware.observation"
              ]
            }
          ]
        },
        "config": {
          "knobs": [
            {
              "name": "sink-addr",
              "env": "SINK_ADDR",
              "type": "string",
              "required": true,
              "control": "operator",
              "description": "UDP sink address for telemetry."
            },
            {
              "name": "sink-tcp-addr",
              "env": "SINK_TCP_ADDR",
              "type": "string",
              "required": true,
              "control": "operator",
              "description": "TCP sink address for sample upload."
            },
            {
              "name": "analysis-timebox-minutes",
              "env": "DETCORDON_ANALYSIS_TTL_MINUTES",
              "type": "integer",
              "required": false,
              "control": "operator",
              "description": "Hard kill timebox for victim containers or VMs."
            }
          ]
        },
        "security": {
          "authMethods": [
            "none"
          ],
          "tenantBoundary": "host-level",
          "dataClasses": [
            "hostile-samples",
            "logs",
            "metrics"
          ],
          "secretAccess": "references-only",
          "revocation": "Stop sandbox and sink services, revoke sample recipient key, and archive encrypted sample store according to incident policy.",
          "auditEvents": [
            "detcordon.event.observed",
            "detcordon.sample.stored"
          ]
        },
        "health": {
          "checks": [
            {
              "name": "workspace-tests",
              "type": "command",
              "target": "cargo test --workspace",
              "intervalSeconds": 86400,
              "timeoutSeconds": 300,
              "required": true
            }
          ]
        },
        "compatibility": {
          "contracts": [
            {
              "name": "detcordon-wire-format",
              "version": "0.1.0",
              "test": "cargo test --workspace"
            }
          ]
        },
        "docs": {
          "readme": "README.md",
          "architecture": "AGENTS.md"
        },
        "metadata": {
          "candidateWave": "component-manifest-candidate-wave",
          "containmentRules": "AGENTS.md"
        }
      },
